window.kbPageData["views/entry/k-4ae19671882e0f38"] = {"key":"entry/k-4ae19671882e0f38","state":{"route":"entry/k-4ae19671882e0f38"},"node":{"id":"k-4ae19671882e0f38","mode":"k","title":"正方体三面共顶点的判定","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["正方体三个不同的面共顶点当且仅当两两相邻","正方体上三个不同的面两两相邻当且仅当它们共用一个顶点"],"qs":["江苏 2024 A类 行测#88","江苏 2024 C类 行测#88"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":2,"repeatPositions":0,"directorySummary":"正方体的三个不同面共用一个顶点，当且仅当它们两两共用一条棱。等价地，这三个面中不能有任何一对相对面。","review":{"definition":"正方体的三个不同面共用一个顶点，当且仅当它们两两共用一条棱。等价地，这三个面中不能有任何一对相对面。","explanation":"正方体有三对相对面，从每对各取一面，三个面就会在唯一一个顶点相交。第88题中，三个不同数字之和为8的组合只有1、2、5和1、3、4。将选项C的展开图折叠后，1、2、5所在的三个面两两相邻，因此共用一个顶点。A、B的两组候选分别含有相对面1与4、2与5，D的两组候选分别含有相对面1与5、3与4。","references":[],"evidence":"面1、面2和面5两两相邻，即三个面存在公共点","disposition":"独立词条","basis":"据原题和解析编释。","title":"正方体三面共顶点的判定","related":[],"examFocus":{"江苏 2024 A类 行测#88":"先按面上数字的和筛选三面组合，再用展开图中的相对面关系判断它们能否共用一个顶点。","江苏 2024 C类 行测#88":"结合三面数字的和与折叠后的相对面关系，判断哪组三个面能共用一个顶点。"}},"readings":[{"origin":"k-4ae19671882e0f38","title":"正方体三面共顶点的判定","qs":["江苏 2024 A类 行测#88"],"definition":"正方体的三个不同面共用一个顶点，当且仅当它们两两共用一条棱。等价地，这三个面中不能有任何一对相对面。","explanation":"正方体有三对相对面，从每对各取一面，三个面就会在唯一一个顶点相交。第88题中，三个不同数字之和为8的组合只有1、2、5和1、3、4。将选项C的展开图折叠后，1、2、5所在的三个面两两相邻，因此共用一个顶点。A、B的两组候选分别含有相对面1与4、2与5，D的两组候选分别含有相对面1与5、3与4。","evidence":"面1、面2和面5两两相邻，即三个面存在公共点","doubt":"","references":[]},{"origin":"k-7f273f880bf77bfa","title":"正方体三面共顶点的判定","qs":["江苏 2024 C类 行测#88"],"definition":"正方体上三个不同的面共用一个顶点，当且仅当它们两两共边。等价地，三个面中只要有一对相对面，就无法共用一个顶点。","explanation":"正方体的六个面分为三对相对面。从每对中各取一个面，就分别确定了顶点在长、宽、高三个方向上的位置。第88题中，从1至6选出三个不同数字，和为8的组合只有1、2、5和1、3、4。B项折叠后，面1、面2、面5两两相邻。A、C、D两项组合各自都含有一对相对面，因此只有B符合题意。","evidence":"面1、面2和面5两两相邻，存在同一个公共顶点","doubt":"","references":[]}]},"questions":{"江苏 2024 A类 行测#88":{"paper":"江苏 2024 A类 行测","n":88,"mod":"判断推理","src":["f8fec75f67d6d1ba5759.pdf",18],"asrc":["0126a1c8aceee632ea2b.pdf",27],"card":"133af5b9f7e9aeb7a1bb1e22","links":[{"id":"k-4ae19671882e0f38","role":"解题依据","why":"用三面是否两两相邻判定其能否共用一个顶点。"}]},"江苏 2024 C类 行测#88":{"paper":"江苏 2024 C类 行测","n":88,"mod":"判断推理","src":["3f1ec77ae8a18519b57e.pdf",18],"asrc":["02d6b49839583bdaf297.pdf",26],"card":"7ed861056c0eb00dce8204e3","links":[{"id":"k-4ae19671882e0f38","role":"解题依据","why":"该性质允许通过检查候选三面中是否含有相对面来判断它们能否共顶点。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-4ae19671882e0f38":[["江苏 2024 A类 行测#88"],["江苏 2024 C类 行测#88"]]}};
